(11212,'Simple meta tags.','','11.4.11'),
(11213,'index - Allow search engines to index this page (assumed).','','11.4.11'),
(11214,'follow - Allow search engines to follow links on this page (assumed).','','11.4.11'),
(11215,'noindex - Prevents search engines from indexing this page.','','11.4.11'),
(11216,'nofollow - Prevents search engines from following links on this page.','','11.4.11'),
(11217,'noarchive - Prevents cached copies of this page from appearing in search results.','','11.4.11'),
(11218,'nosnippet - Prevents descriptions from appearing in search results, and prevents page caching.','','11.4.11'),
(11219,'noimageindex - Prevent search engines from indexing images on this page.','','11.4.11'),
(11220,'notranslate - Prevent search engines from offering to translate this page in search results.','','11.4.11'),
